// deployment.json is generated by `npm run deploy:local` in /blockchain. It holds
// only public data (chain id, address, ABI). The glob keeps the build working
// before the contract has been deployed.
const modules = import.meta.glob('../contracts/deployment.json', { eager: true, import: 'default' });
export const deployment = Object.values(modules)[0] ?? null;

export const EXPECTED_CHAIN_ID = deployment?.chainId ?? 31337;
export const NETWORK_NAME = deployment?.networkName ?? 'Hardhat Local';

// ethers is loaded on demand so it stays out of the initial bundle.
export const loadEthers = () => import('ethers');
let contractInterface = null;

export async function getMindChain(runner) {
  if (!deployment) {
    throw new Error('The MindChain contract has not been deployed. Run `npm run deploy:local` in /blockchain.');
  }
  const { Contract } = await loadEthers();
  const contract = new Contract(deployment.address, deployment.abi, runner);
  contractInterface ??= contract.interface;
  return contract;
}

const CUSTOM_ERROR_MESSAGES = {
  AlreadyRegistered: 'This wallet is already registered on MindChain.',
  NotRegisteredPatient: 'Register your wallet on MindChain first.',
  InvalidTherapist: 'That therapist wallet address is not valid.',
  InvalidExpiry: 'The access expiry must be in the future.',
  NoActiveGrant: 'This therapist does not currently have access.',
  InvalidRecordId: 'The record ID is invalid.',
  InvalidDigest: 'The record fingerprint is invalid.',
  RecordAlreadyExists: 'This record is already anchored on-chain.',
  RecordNotFound: 'This record is not on-chain yet.',
  NotRecordOwner: 'This record belongs to a different wallet.',
  RecordIsRevoked: 'This record has been withdrawn on-chain.',
  DigestUnchanged: 'The on-chain fingerprint is already up to date.',
};

// Converts MetaMask / ethers / contract errors into a readable message.
export function describeChainError(err) {
  const code = err?.code ?? err?.info?.error?.code;
  if (code === 'ACTION_REJECTED' || code === 4001) return 'You rejected the request in MetaMask.';
  if (code === -32002) return 'MetaMask already has a pending request. Open MetaMask to continue.';
  if (code === 'INSUFFICIENT_FUNDS') return 'This wallet does not have enough ETH to pay for gas.';

  const revertName = err?.revert?.name;
  if (revertName && CUSTOM_ERROR_MESSAGES[revertName]) return CUSTOM_ERROR_MESSAGES[revertName];

  const data = err?.data ?? err?.info?.error?.data ?? err?.error?.data;
  if (contractInterface && typeof data === 'string' && data.startsWith('0x')) {
    try {
      const parsed = contractInterface.parseError(data);
      if (parsed && CUSTOM_ERROR_MESSAGES[parsed.name]) return CUSTOM_ERROR_MESSAGES[parsed.name];
    } catch {
      /* not a MindChain error */
    }
  }
  if (code === 'NETWORK_ERROR' || code === 'SERVER_ERROR') {
    return 'Cannot reach the blockchain network. Is the local Hardhat node running?';
  }
  if (code === 'CALL_EXCEPTION') return 'The transaction was reverted by the contract.';
  return err?.shortMessage ?? err?.message ?? 'Blockchain request failed.';
}
